#include <iostream>
#include <string>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    long long ans = 0;
    bool met = false;
    std::string line;

    while (std::getline(std::cin, line)) {
        int countB = 0;
        for (char c : line) {
            if (c == 'B') countB++;
        }

        if (line == "BBBBBBBB") {
            ans++;
        } else if (!met) {
            if (countB > 0) {
                ans += countB;
            }
            met = true;
        }
    }

    std::cout << ans << std::endl;

    return 0;
}

